def transform(grid):
    if not grid or not grid[0]:
        return grid

    # Background color from top-left corner
    bg = grid[0][0]
    result = []

    for row in grid:
        # Find the index of the first non-background cell (foreground)
        first_fg_idx = None
        for i, cell in enumerate(row):
            if cell != bg:
                first_fg_idx = i
                break

        # Build the output row
        new_row = []
        for i, cell in enumerate(row):
            # If we have a foreground cell and this cell is background
            # and is AFTER the first foreground cell, replace with 1
            if first_fg_idx is not None and i > first_fg_idx and cell == bg:
                new_row.append(1)
            # Otherwise keep the original cell
            else:
                new_row.append(cell)

        result.append(new_row)

    return result
